    function _pointsAttr(points) {
      return points.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
    }

    /**
     * plotFunction(id, opts) → handle
     *   opts: { expr | fn, variables=['x'], domain, samples=200,
     *           stroke='#1f77b4', width=2, dashed=false }
     * The drawn polyline is ALWAYS produced by sampling the compiled function
     * across `domain`. Non-finite samples split the line into segments instead
     * of drawing a spike.
     */
    function plotFunction(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['x'];
      var group = _plotFrame.draw.group().attr('id', 'plot-' + id);
      var handle = {
        id: id,
        node: group,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        domain: opts.domain || _plotFrame.xDomain.slice(),
        samples: opts.samples || 200,
        setExpr: function (src) { this.fn = _resolveFn(src, vars); return this.sample(); },
        setFn: function (f) { this.fn = f; return this.sample(); },
        setDomain: function (dm) { this.domain = dm; return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          if (!this.fn) return this;
          var segs = _sampleSegments(this.fn, this.domain, this.samples);
          for (var s = 0; s < segs.length; s++) {
            if (segs[s].length < 2) continue;
            var line = group.polyline(_pointsAttr(segs[s]))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4',
                width: opts.width || 2,
                linecap: 'round',
                linejoin: 'round'
              });
            if (opts.dashed) line.attr('stroke-dasharray', '5,4');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** Sample fn across domain, splitting at non-finite values. → [[ [px,py], … ], …] */
    function _sampleSegments(fn, domain, samples) {
      var a = domain[0], b = domain[1], n = Math.max(2, samples | 0);
      var segs = [], cur = [];
      for (var i = 0; i < n; i++) {
        var t = a + (b - a) * (i / (n - 1));
        var v;
        try { v = fn(t); } catch (e) { v = NaN; }
        if (typeof v === 'number' && isFinite(v)) {
          cur.push([plotX(t), plotY(v)]);
        } else if (cur.length) {
          segs.push(cur);
          cur = [];
        }
      }
      if (cur.length) segs.push(cur);
      return segs;
    }

    /**
     * fillBetween(id, opts) → handle
     *   opts: { lower, upper, variables=['x'], domain, samples=200,
     *           fill='#7fb3ff', opacity=0.45, stroke, strokeWidth=1 }
     * `lower` / `upper` may be expression strings or functions. The polygon is
     * built from EVERY sampled point on both boundaries, so a curved boundary
     * produces a curved region with no caller involvement.
     */
    function fillBetween(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['x'];
      var group = _plotFrame.draw.group().attr('id', 'fill-' + id);
      var handle = {
        id: id,
        node: group,
        lower: opts.lower != null ? _resolveFn(opts.lower, vars) : function () { return 0; },
        upper: opts.upper != null ? _resolveFn(opts.upper, vars) : function () { return 0; },
        domain: opts.domain || _plotFrame.xDomain.slice(),
        samples: opts.samples || 200,
        setLower: function (src) { this.lower = _resolveFn(src, vars); return this.sample(); },
        setUpper: function (src) { this.upper = _resolveFn(src, vars); return this.sample(); },
        setDomain: function (dm) { this.domain = dm; return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.domain[0], b = this.domain[1], n = Math.max(2, this.samples | 0);
          var top = [], bottom = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var lo, hi;
            try { lo = this.lower(t); hi = this.upper(t); } catch (e) { lo = NaN; hi = NaN; }
            if (isFinite(lo) && isFinite(hi)) {
              top.push([plotX(t), plotY(hi)]);
              bottom.push([plotX(t), plotY(lo)]);
            }
          }
          if (top.length < 2) return this;
          bottom.reverse();
          var poly = group.polygon(_pointsAttr(top.concat(bottom)))
            .fill({
              color: opts.fill || '#7fb3ff',
              opacity: (opts.opacity == null) ? 0.45 : opts.opacity
            });
          if (opts.stroke) {
            poly.stroke({ color: opts.stroke, width: opts.strokeWidth || 1, linejoin: 'round' });
          } else {
            poly.stroke('none');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /**
     * plotParametric(id, opts) → handle
     *   opts: { x, y, variables=['t'], tDomain=[0,1], samples=200, stroke, width }
     */
    function plotParametric(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['t'];
      var group = _plotFrame.draw.group().attr('id', 'param-' + id);
      var handle = {
        id: id,
        node: group,
        fx: _resolveFn(opts.x, vars),
        fy: _resolveFn(opts.y, vars),
        tDomain: opts.tDomain || [0, 1],
        samples: opts.samples || 200,
        setX: function (src) { this.fx = _resolveFn(src, vars); return this.sample(); },
        setY: function (src) { this.fy = _resolveFn(src, vars); return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.tDomain[0], b = this.tDomain[1], n = Math.max(2, this.samples | 0);
          var pts = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var vx, vy;
            try { vx = this.fx(t); vy = this.fy(t); } catch (e) { vx = NaN; vy = NaN; }
            if (isFinite(vx) && isFinite(vy)) pts.push([plotX(vx), plotY(vy)]);
          }
          if (pts.length >= 2) {
            group.polyline(_pointsAttr(pts))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4', width: opts.width || 2,
                linecap: 'round', linejoin: 'round'
              });
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** integrateSimpson(fn, a, b, n=200) → number. Composite Simpson's rule. */
    function integrateSimpson(fn, a, b, n) {
      n = Math.max(2, n || 200);
      if (n % 2) n++;
      var h = (b - a) / n, s = fn(a) + fn(b);
      for (var i = 1; i < n; i++) s += fn(a + i * h) * ((i % 2) ? 4 : 2);
      return (s * h) / 3;
    }

    /** findRoot(fn, a, b, tol=1e-9) → number | null. Bisection; null if no sign change. */
    function findRoot(fn, a, b, tol) {
      tol = tol || 1e-9;
      var fa = fn(a), fb = fn(b);
      if (!isFinite(fa) || !isFinite(fb) || fa * fb > 0) return null;
      for (var i = 0; i < 200; i++) {
        var m = (a + b) / 2, fm = fn(m);
        if (!isFinite(fm)) return null;
        if (Math.abs(fm) < tol || (b - a) / 2 < tol) return m;
        if (fa * fm < 0) { b = m; } else { a = m; fa = fm; }
      }
      return (a + b) / 2;
    }

    /* ── Equation input binding ──────────────────────────────────────────── */
    /**
     * The error slot is keyed PER INPUT (id "eq-err-<inputId>"), never just
     * "the first .eq-err under my parent": generated figures routinely put
     * several equation inputs under one parent, and a shared slot means a valid
     * edit of field B hides field A's still-current parse error, leaving A's
     * curve stale with nothing on screen to explain why.
     * The .eq-err class is kept so the scaffold CSS still applies.
     *
     * DUPLICATED: keep in sync with _equationErrorSlot in base_scene_new.html.
     */
    function _equationErrorSlot(input) {
      var parent = input.parentNode || document.getElementById('ui');
      if (input.id) {
        var slotId = 'eq-err-' + input.id;
        var byId = document.getElementById(slotId);
        if (byId) return byId;
        var namedSpan = document.createElement('span');
        namedSpan.id = slotId;
        namedSpan.className = 'eq-err';
        namedSpan.style.display = 'none';
        parent.appendChild(namedSpan);
        return namedSpan;
      }
      var existing = parent.querySelector('.eq-err');
      if (existing) return existing;
      var span = document.createElement('span');
      span.className = 'eq-err';
      span.style.display = 'none';
      parent.appendChild(span);
      return span;
    }

    /**
     * _resolveEqTarget(inputId, t) → function(fn, src)
     * Turns one bindEquationInput target into a concrete applier, and THROWS on
     * anything it cannot drive. Silently skipping an unrecognised target is the
     * worst possible outcome: the figure renders, typing changes nothing, and
     * nothing reports it. Throwing makes verify2dHtml catch the mistake at
     * generation time instead of the student discovering it.
     *
     * DUPLICATED: keep in sync with _resolveEqTarget in base_scene_new.html.
     */
    function _resolveEqTarget(inputId, t) {
      if (typeof t === 'function') {
        return function (fn, src) { t(fn, src); };
      }
      if (t && t.handle) {
        var method = t.method || 'setFn';
        if (typeof t.handle[method] !== 'function') {
          throw new Error(
            'bindEquationInput("' + inputId + '"): target handle has no method "' + method +
            '". Use { handle, method: \'...\' } with a method the handle really has ' +
            '(plotFunction: setExpr, setFn; fillBetween: setLower, setUpper; ' +
            'plotParametric: setX, setY).'
          );
        }
        return function (fn) { t.handle[method](fn); };
      }
      if (t && typeof t.setFn === 'function') {
        return function (fn) { t.setFn(fn); };
      }
      throw new Error(
        'bindEquationInput("' + inputId + '"): this target cannot be driven — it is not a ' +
        'function and has no .setFn. Handles without .setFn (fillBetween, plotParametric) ' +
        'must be passed as { handle, method: \'setUpper\' } naming the setter to call.'
      );
    }

    /**
     * bindEquationInput(inputId, targets, opts) → { apply, input, errorSlot }
     *   targets: a plot handle, a { handle, method } pair, a function(fn, src),
     *            or an array of any of those.
     *   opts   : { variables=['x'], onChange(fn, src) }
     *
     * On every valid edit, every target re-samples. On a parse error the last
     * good curve is kept and the message is shown inline — this function NEVER
     * substitutes a hardcoded default.
     * Throws at bind time on a target it cannot drive (see _resolveEqTarget).
     *
     * DUPLICATED: keep in sync with bindEquationInput in base_scene_new.html.
     */
    function bindEquationInput(inputId, targets, opts) {
      opts = opts || {};
      var input = document.getElementById(inputId);
      if (!input) throw new Error('bindEquationInput: no element with id "' + inputId + '"');
      var vars = opts.variables || ['x'];
      var list = Array.isArray(targets) ? targets : [targets];
      var slot = _equationErrorSlot(input);
      // Validated once, loudly, before anything is wired up.
      var appliers = [];
      for (var k = 0; k < list.length; k++) appliers.push(_resolveEqTarget(inputId, list[k]));

      function apply(src) {
        try {
          // The dispatch is INSIDE the try as well: an error thrown while
          // applying (a target callback that throws, a handle mutated later)
          // would otherwise escape uncaught from the input event handler and
          // leave the figure stale with no visible reason.
          var fn = compileExpr(src, vars);
          for (var i = 0; i < appliers.length; i++) appliers[i](fn, src);
          if (typeof opts.onChange === 'function') opts.onChange(fn, src);
        } catch (e) {
          slot.textContent = e.message;
          slot.style.display = '';
          input.setAttribute('data-eq-valid', 'false');
          return false;
        }
        slot.textContent = '';
        slot.style.display = 'none';
        input.setAttribute('data-eq-valid', 'true');
        return true;
      }

      input.addEventListener('input', function () { apply(input.value); });
      apply(input.value);
      return { apply: apply, input: input, errorSlot: slot };
    }

    // @FIGURE_CODE_BEGIN
    // @FIGURE_CODE_END

    // Decide the panel layout once the generated UI exists. Runs last so it sees
    // the final #ui content; a setUiLayout() call in the block above wins.
    _autoUiLayout();
  </script>
</body>

</html>

GLOBALS (do not re-declare): showPopup(title,body), showTooltip(text,event), hideTooltip(), #container (mount target), window.__markRendered() (call once when drawn), 'fig-resize' CustomEvent on document, setUiLayout(mode, sizePx).
  #ui is always docked as a right-side column by the scaffold and grows to fit its content. setUiLayout(...) exists only for backwards compatibility and cannot change the side, overlay state, or size. Just put controls in #ui. Never restyle #ui's position/width/max-height and never build your own side panel. Docking resizes #container and fires 'fig-resize', so setPlotFrame re-lays the figure out at its new size.

LIBRARY: SVG.js v3 (global: SVG). var draw=SVG().addTo(document.getElementById('container')).size('100%','100%'); var W=600,H=Math.round(W*(3/4)); draw.viewbox(0,0,W,H). font-size in user units (no px). Hover: el.on('mousemove',e=>showTooltip('label',e)).on('mouseleave',()=>hideTooltip()).on('click',()=>showPopup('Title','body')); el.css('cursor','pointer'). window.__markRendered() synchronously at end.
PLOTTING HELPERS (do not re-declare, and do NOT define your own X()/Y() — use plotX/plotY):
  setPlotFrame({ xDomain, yDomain, margin }) → call ONCE before creating plots; establishes world→screen and owns resize (do not write your own plot resize handler)
  plotX(worldX) / plotY(worldY) → screen px
  compileExpr(src, vars) → f(...args); throws on a bad expression and never returns a fallback
  bindEquationInput(inputId, targets, { variables, onChange }) → wires an <input> to plot handles and shows parse errors inline
  plotFunction(id, { expr, variables, domain, samples, stroke, width, dashed }) → handle
  fillBetween(id, { lower, upper, variables, domain, samples, fill, opacity }) → handle
  plotParametric(id, { x, y, variables, tDomain, samples, stroke }) → handle
  variables: the argument names the expression may use, in order (defaults: plotFunction ['x'], fillBetween ['x'], plotParametric ['t']). When a blueprint field declares "variables" you MUST pass that same array to BOTH the plot constructor and bindEquationInput — plotFunction('f', { expr: 't^2' }) without { variables: ['t'] } throws "Unknown variable t" at construction and kills the whole figure.
  integrateSimpson(fn, a, b, n) → number;  findRoot(fn, a, b, tol) → number | null
  Handles re-sample on EVERY setter call, and the setters differ: plotFunction → .setExpr / .setFn / .setDomain · fillBetween → .setLower / .setUpper / .setDomain · plotParametric → .setX / .setY. All handles also have .sample() and .remove().

VISUAL FIDELITY: the default state must be a faithful inline replacement for the source image.
- Color scheme: match every color exactly — axis lines, data series, fills, backgrounds
- Layout & proportions: same relative element positions, same axis ranges, same tick marks and gridlines
- Data shape: match curve trajectories, bar heights, scatter clusters, or node/edge layout — approximate magnitudes, not invented
- Labels & annotations: every label visible in the original must appear at the same position; use blueprint.reconstructionNotes for text and color coding
- Line styles: dashed vs solid, stroke weights, arrowhead presence — copy from the image
- The step-0 (default) state should look indistinguishable from the original at a glance, with no title bar or toolbar visible

TEXT PLACEMENT & READABILITY: faithful labels must still be readable.
- Treat every label, tick label, annotation, formula, and legend item as a collision-checked box, and check each one against lines, arrows, curves, points, nodes, tick marks, gridlines, controls, and other text before finalizing. Text must not sit on top of strokes or dense marks.
- If the source label is anchored to a busy line/arrow/node, keep the semantic anchor but move the text to the nearest open whitespace and connect it with a short leader line, pointer, or subtle dot.
- Draw text and label backgrounds after geometry so labels are on top. Over busy regions add a small white/translucent background rect, or a halo: text.attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round' }).
- Do not add extra visible explanatory text inside the figure; use hover tooltips, click popups, and the scaffold narration panel for explanation.

SCALE SAFETY: figures may be stitched into chapters at different sizes.
- With Canvas, Chart.js custom drawing, or any pixel-based renderer, derive point radius, stroke width, arrowheads, ticks, label size, and annotation padding from min(plotWidth, plotHeight). Avoid large fixed pixel minimums such as Math.max(20, scaledRadius); use only small clamps that prevent invisibility.
- With SVG/viewBox geometry that already scales naturally, preserve that and avoid fixed px sizes that break it.
- If space is small, simplify or hide secondary labels instead of making marks oversized.

HOVER/CLICK (on user action only): hover → showTooltip(label,event)/hideTooltip(); cursor:pointer on interactive elements. Click → showPopup('Title','2–3 sentence explanation'). Animation: fill/opacity transitions only; no scale/translate/bounce.

CONTROLS (blueprint.interactions — render in UI section; add id="{id}Input" to every input). Each control's handler must teach the concept described in its "teaches" field:
  slider → <label>{label}: <output id="{id}Val">{default}</output><input id="{id}Input" type="range" min="{min}" max="{max}" step="{step}" value="{default}" oninput="document.getElementById('{id}Val').value=this.value;update_{id}(+this.value)"></label>  +  function update_{id}(v){}
  toggle → <label><input id="{id}Input" type="checkbox" onchange="toggle_{id}(this.checked)"> {label}</label>  +  function toggle_{id}(on){}
  button → <button onclick="trigger_{id}()">{label}</button>  +  function trigger_{id}(){}
  equation_input → one <label>{field.label} <input id="{field.id}Input" value="{field.default}"></label> per entry in the interaction's "fields"
  code_editor → a <textarea id="{id}Code"> plus sample tabs, an input for the interaction's "input", a Run button, and playback controls

CODE EDITOR (an interaction has type "code_editor") — build a trace-and-playback workbench, not a run-once box. The student writes algorithm logic, never drawing code; every mark the figure draws comes from a recorded frame.
Each op in the interaction's "api" appends a frame BEFORE returning its value — { kind (which op ran; drives caption wording and highlight style), state (a deep copy of the data at that instant), indices (the elements the op touched; highlight exactly these), message (one human-readable line, e.g. "compare A[3]=2 with A[7]=14 → false") } — and an op is the ONLY route to mutation, which is what makes the replay gap-free. Freeze the API object, range-check every index, and expose no reference to the underlying data. Seed a <textarea> with "sample_code", add tabs to swap in "buggy_code" and a bare starter, an editable field for the interaction's "input", and a Run button that disables while running — all inside #ui, which the scaffold keeps in a real right-side column, shrinking #container and firing 'fig-resize' so the figure re-lays out. Execute in a Web Worker built from a Blob URL (revoke it when done) with a ~1–2s wall-clock timeout AND hard caps on op and frame count; never eval student code on the main thread. Surface syntax errors, thrown errors, timeouts, cap hits, and a missing or misnamed "entry_point" inline as the final frame with a clear message, never as a silent no-op. Replay with first / prev / play-pause / next, a speed control, an "n of N" counter, the current frame's message as caption, and a running log; draw the structure from frame[i] alone so scrubbing backwards looks identical to arriving there forwards — do not accumulate SVG elements across frames (reuse a group you clear, or update existing shapes in place). Finally test the final state against "success_check" and show a status readout distinguishing not-run / running / correct / wrong answer / error — on a wrong answer, highlight the elements that violate the property so the buggy sample is diagnosable rather than merely marked wrong.

DEMO STEPS (blueprint.demo_steps): if present and non-empty, build a step player in #ui:
  - A <p id="demoNarration" style="margin:0;font-size:10px;max-width:180px"> showing the current step's narration
  - <button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button>
  - Each step's .state sets matching interaction inputs to the specified values and calls their update functions
  - Step 0 is the default view (set on load); subsequent steps are one click away
  - Omit the player entirely if demo_steps is absent or empty

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A hash function h maps each actual key to a slot of table T, and when several keys collide they are simply strung together in that slot's linked list — so the choice of h alone decides how evenly the keys spread and how long the chains get.
KEY INSIGHT (what students should walk away understanding): Chaining makes collisions harmless but not free — the hash function is the only thing standing between a table of short constant-time chains and a single long list.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A hash function h maps each actual key to a slot of table T, and when several keys collide they are simply strung together in that slot's linked list — so the choice of h alone decides how evenly the keys spread and how long the chains get.",
  "figureType": "diagram",
  "elements": [
    "Large outer dark-gray ellipse labeled 'U (universe of keys)'",
    "Inner light-gray ellipse labeled 'K (actual keys)' nested inside U",
    "Eight filled black dots inside K labeled k1…k8, each with its numeric key value shown on hover/next to the label",
    "Vertical column of table slots in the center, labeled 'T' above the top slot",
    "Empty slots drawn as dark-gray rectangles with a diagonal slash (NIL)",
    "Occupied slots drawn as white/light rectangles containing a short horizontal stub line that becomes the head pointer",
    "Slot index labels 0..m-1 running down the left edge of T",
    "Curved/straight arrows from each key dot in K to its slot in T (the hash function h made visible)",
    "Four doubly linked chains to the right of T, one per occupied slot",
    "Each list node drawn as a three-cell box: left prev-pointer cell, center key-label cell (k1, k4, …), right next-pointer cell",
    "Forward arrows (next) and backward arrows (prev) between consecutive nodes in a chain",
    "Diagonal slash in the prev cell of the head node and the next cell of the tail node to mark NIL",
    "Head arrow from each occupied slot into the first node of its chain",
    "Chain-length badge next to each chain (e.g. '2', '3', '1', '2')",
    "Load-factor readout α = n/m displayed near T",
    "Caption/legend: slash = NIL, gray = empty slot"
  ],
  "interactions": [
    {
      "id": "hashCode",
      "type": "code_editor",
      "label": "Define the hash function and insert every key",
      "teaches": "That the entire chain structure — which slots are empty, which are long — is produced by one expression h(k), and that keys are prepended to a chain in insertion order",
      "entry_point": "hashAll(keys)",
      "api": [
        {
          "op": "m()",
          "does": "returns the number of slots in T (set by the table-size slider)"
        },
        {
          "op": "insert(k, i)",
          "does": "prepends key k to the chain at slot i and draws its arrow from K — the ONLY way to change the figure; errors if i is not an integer in [0, m())"
        },
        {
          "op": "chainLength(i)",
          "does": "returns how many keys currently sit in slot i (read-only)"
        },
        {
          "op": "note(msg)",
          "does": "attaches your own comment to the current frame"
        }
      ],
      "frame": "the whole figure after one op: the K circle with the arrow just drawn for the current key highlighted, the slot it landed in flashing, and that slot's chain redrawn with the new head node",
      "input": {
        "label": "Actual keys (numeric values of k1…k8)",
        "default": "11, 25, 17, 41, 15, 28, 35, 18"
      },
      "sample_code": "function hashAll(keys) {\n  for (const k of keys) {\n    const i = k % m();        // division method\n    note('h(' + k + ') = ' + i);\n    insert(k, i);\n  }\n}",
      "buggy_code": "function hashAll(keys) {\n  for (const k of keys) {\n    // BUG: table size hardcoded as 10 instead of m(),\n    // so slots go out of range (or are never used) when m changes\n    const i = k % 10;\n    insert(k, i);\n  }\n}",
      "success_check": "every input key appears in exactly one chain, and each key k sits in slot h(k) with 0 <= h(k) < m()"
    },
    {
      "id": "tableSize",
      "type": "slider",
      "label": "Table size m (number of slots)",
      "teaches": "How the same keys and the same expression k % m() redistribute as m changes — a bad m (e.g. a multiple of a pattern in the keys) piles keys into few chains and drives the load factor up",
      "range": [
        4,
        16,
        1
      ],
      "default": 10
    },
    {
      "id": "highlightChain",
      "type": "click",
      "teaches": "Which keys in K collided, by lighting up one slot together with every key dot and arrow that maps to it — searching that slot means walking exactly that chain"
    }
  ],
  "demo_steps": [
    {
      "title": "The universe and the actual keys",
      "narration": "U holds every key that could ever occur; only the handful in K are really stored. The table T has far fewer slots than |U|, so some keys must share.",
      "state": {
        "tableSize": 10
      }
    },
    {
      "title": "Run h(k) = k mod m",
      "narration": "The sample code walks the keys and calls insert(k, k % m()). Watch each arrow get drawn one at a time: k1 and k4 both land in slot 1, so the second one is simply prepended in front of the first.",
      "state": {
        "tableSize": 10
      }
    },
    {
      "title": "A collision is just a longer list",
      "narration": "Slot 5 receives three keys and holds a chain of three nodes; slot 7 holds one; five slots stay NIL. Chaining never rejects a key — it only lengthens a list.",
      "state": {
        "tableSize": 10
      }
    },
    {
      "title": "Shrink the table",
      "narration": "Drop m to 5 and re-run: the same eight keys crowd into fewer slots, chains double in length and the load factor α = n/m jumps — search time follows chain length, not table size.",
      "state": {
        "tableSize": 5
      }
    },
    {
      "title": "A bad hash function",
      "narration": "Load the buggy version (or try 'return 0'): every key funnels into one slot and the hash table degenerates into a single linked list with Θ(n) search. Then fix h and watch the chains flatten out again.",
      "state": {
        "tableSize": 10
      }
    }
  ],
  "keyInsight": "Chaining makes collisions harmless but not free — the hash function is the only thing standing between a table of short constant-time chains and a single long list.",
  "reconstructionNotes": "Three-band layout left→right. Left: two concentric ellipses, outer filled medium gray labeled 'U (universe of keys)' at top, inner filled light gray labeled 'K (actual keys)' at left; eight small filled black dots scattered in the inner ellipse, italic subscripted labels k1…k8 placed just left of or below each dot, with the numeric key value shown in small type. Center: a narrow vertical stack of equal-height rectangles forming T, title 'T' above; empty slots filled dark gray with a thin diagonal slash, occupied slots filled near-white with a short horizontal pointer stub; small index numbers 0..m-1 outside the left edge; an α = n/m readout beneath. Thin black straight arrows run from each key dot across to the left edge of its slot, crossing each other freely — crossings are the visual signature of the hash. Right: for each occupied slot, a horizontal chain of three-cell node boxes (light gray fill, black strokes) with the key label centered; forward next-arrows along the top between boxes and backward prev-arrows along the bottom, diagonal slashes marking NIL in the head's prev cell and the tail's next cell. Highlighting a slot on click should tint the slot, its arrows, its key dots in K, and its whole chain in a single accent color (e.g. orange) while everything else dims. Newly inserted nodes flash at the head of the chain during code replay."
}

Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<b style="font-size:12px">Hashing with chaining</b>
<span id="demoNarration" style="display:block;font-size:11px;line-height:1.45;min-height:66px;background:#fff;border:1px solid #e2e5e9;border-radius:4px;padding:6px 7px"></span>
<span style="display:flex;gap:4px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="flex:1;text-align:center;font-size:11px"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label>Table size m (slots): <output id="tableSizeVal">10</output>
  <input id="tableSizeInput" type="range" min="4" max="16" step="1" value="10" oninput="document.getElementById('tableSizeVal').value=this.value;update_tableSize(+this.value)">
</label>
<label>Actual keys (values of k₁…k₈)
  <input id="hashCodeInput" value="11, 25, 17, 41, 15, 28, 35, 18">
</label>
<span style="font-size:11px"><b>Define h and insert every key</b> — API: <code>m()</code>, <code>insert(k,i)</code>, <code>chainLength(i)</code>, <code>note(msg)</code>; entry point <code>hashAll(keys)</code></span>
<span style="display:flex;gap:3px;flex-wrap:wrap">
  <button id="tab-sample" onclick="setTab('sample')">Sample</button>
  <button id="tab-buggy" onclick="setTab('buggy')">Buggy</button>
  <button id="tab-bad" onclick="setTab('bad')">h(k)=0</button>
  <button id="tab-blank" onclick="setTab('blank')">Blank</button>
</span>
<textarea id="hashCodeCode" spellcheck="false"></textarea>
<span style="display:flex;gap:6px;align-items:center">
  <button id="runBtn" onclick="trigger_hashCode()">▶ Run</button>
  <span id="runStatus" style="font-size:11px;color:#666">not run</span>
</span>
<span style="display:flex;gap:3px;align-items:center">
  <button onclick="pbFirst()" title="first">⏮</button>
  <button onclick="pbPrev()" title="previous">◀</button>
  <button id="playBtn" onclick="pbPlay()" title="play / pause">▶</button>
  <button onclick="pbNext()" title="next">▶|</button>
  <span id="frameCounter" style="font-size:11px;color:#555">0 of 0</span>
</span>
<label>Replay speed: <output id="speedVal">1.00</output>×
  <input id="speedInput" type="range" min="0.25" max="4" step="0.25" value="1" oninput="document.getElementById('speedVal').value=(+this.value).toFixed(2)">
</label>
<span id="frameCaption" style="display:block;font-size:11px;min-height:28px;color:#222"></span>
<span id="runLog" style="display:block;white-space:pre-wrap;font-family:ui-monospace,Consolas,monospace;font-size:10px;line-height:1.35;max-height:120px;overflow:auto;background:#fff;border:1px solid #e2e5e9;border-radius:4px;padding:5px"></span>
<span style="font-size:10px;color:#666">Click a slot, a key dot, or a chain node to light up one collision set; click the background to clear.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var FW = 1200, FH = 500;
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, FW, FH);
var figScene = figDraw.group();

var ACCENT = '#e8791e', DIMOP = 0.26;
var SERIF = 'Georgia,"Times New Roman",serif';
var SANS = 'Helvetica,Arial,sans-serif';

/* geometry */
var UCX = 223, UCY = 261, URX = 218, URY = 224;
var KCX = 212, KCY = 304, KRX = 168, KRY = 142;
var TX = 560, TW = 92, TTOP = 44, TBOT = 452;
var CX0 = 708, AVW = 436;

var KEYPOS = [
  { x: 194, y: 204, dx: -7, dy: 14, an: 'end' },
  { x: 239, y: 337, dx: -7, dy: 14, an: 'end' },
  { x: 362, y: 348, dx: -9, dy: 1, an: 'end' },
  { x: 229, y: 257, dx: -7, dy: 14, an: 'end' },
  { x: 329, y: 260, dx: -9, dy: 1, an: 'end' },
  { x: 194, y: 381, dx: -9, dy: 1, an: 'end' },
  { x: 273, y: 280, dx: -7, dy: 14, an: 'end' },
  { x: 295, y: 360, dx: -9, dy: 1, an: 'end' }
];
var SUB = ['\u2081', '\u2082', '\u2083', '\u2084', '\u2085', '\u2086', '\u2087', '\u2088', '\u2089'];
function klabel(i) { return 'k' + (i < 9 ? SUB[i] : String(i + 1)); }

var S = { m: 10, keys: [11, 25, 17, 41, 15, 28, 35, 18], chains: [], highlight: null, flashSlot: -1, flashK: -1, bad: null };
var FR = { frames: [], i: 0, timer: 0, playing: false, running: false };

/* ---------- small helpers ---------- */
function txt(g, x, y, s, size, o) {
  o = o || {};
  var t = g.text(String(s));
  t.font({ family: o.family || SERIF, size: size, anchor: o.anchor || 'middle', style: o.italic ? 'italic' : 'normal', weight: o.weight || 'normal', leading: 1 });
  t.fill(o.fill || '#000');
  t.attr({ x: x, y: y });
  t.attr('dominant-baseline', 'central');
  var kids = t.node.childNodes;
  for (var i = 0; i < kids.length; i++) { if (kids[i].setAttribute) { kids[i].setAttribute('x', x); kids[i].setAttribute('dy', 0); } }
  t.attr('pointer-events', 'none');
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
  return t;
}
function arrow(g, x1, y1, x2, y2, color, w, op) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L, hl = Math.min(8, L * 0.45), hw = hl * 0.42;
  var bx = x2 - ux * hl, by = y2 - uy * hl;
  g.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'round' }).opacity(op).attr('pointer-events', 'none');
  g.polygon([x2, y2, bx - uy * hw, by + ux * hw, bx + uy * hw, by - ux * hw].join(','))
    .fill(color).opacity(op).attr('pointer-events', 'none');
}
function slotH() { return (TBOT - TTOP) / S.m; }
function slotY(i) { return TTOP + i * slotH(); }
function slotOp(i) { return (S.highlight === null) ? 1 : (i === S.highlight ? 1 : DIMOP); }
function isAccent(i) { return (S.highlight === i) || (S.highlight === null && S.flashSlot === i); }
function keySlotMap() {
  var mp = {};
  for (var i = 0; i < S.chains.length; i++) for (var j = 0; j < S.chains[i].length; j++) {
    var n = S.chains[i][j]; if (n.kIdx >= 0) mp[n.kIdx] = { slot: i, pos: j };
  }
  return mp;
}

/* ---------- drawing ---------- */
function drawUniverse(g) {
  g.ellipse(2 * URX, 2 * URY).center(UCX, UCY).fill('#9b9b9b').stroke({ color: '#000', width: 2 }).attr('pointer-events', 'none');
  g.ellipse(2 * KRX, 2 * KRY).center(KCX, KCY).fill('#e9e9e9').stroke({ color: '#000', width: 2 }).attr('pointer-events', 'none');
  txt(g, 233, 88, 'U', 21, { italic: true });
  txt(g, 224, 118, '(universe of keys)', 15);
  txt(g, 110, 250, 'K', 21, { italic: true });
  txt(g, 108, 282, '(actual', 15);
  txt(g, 104, 305, 'keys)', 15);
}
function drawArrows(g) {
  var sh = slotH();
  for (var i = 0; i < S.m; i++) {
    var ch = S.chains[i], A = ch.length; if (!A) continue;
    for (var j = 0; j < A; j++) {
      var n = ch[j]; if (n.kIdx < 0 || n.kIdx >= KEYPOS.length) continue;
      var p = KEYPOS[n.kIdx];
      var ty = slotY(i) + sh * ((j + 1) / (A + 1)), tx = TX - 3;
      var dx = tx - p.x, dy = ty - p.y, L = Math.sqrt(dx * dx + dy * dy) || 1;
      var acc = isAccent(i) || (S.highlight === null && S.flashK === n.kIdx);
      arrow(g, p.x + dx / L * 7, p.y + dy / L * 7, tx, ty, acc ? ACCENT : '#000', acc ? 1.9 : 1.1, slotOp(i));
    }
  }
}
function drawDots(g, map) {
  for (var i = 0; i < KEYPOS.length; i++) {
    if (i >= S.keys.length) continue;
    var p = KEYPOS[i], info = map[i];
    var op = (S.highlight === null) ? 1 : (info && info.slot === S.highlight ? 1 : DIMOP);
    var acc = (info && S.highlight === info.slot) || (S.highlight === null && S.flashK === i);
    if (S.bad && S.bad.indexOf(i) >= 0) g.circle(18).center(p.x, p.y).fill('none').stroke({ color: '#c62828', width: 2 }).opacity(op).attr('pointer-events', 'none');
    var c = g.circle(9.5).center(p.x, p.y).fill(acc ? ACCENT : '#000').opacity(op).css('cursor', 'pointer');
    txt(g, p.x + p.dx, p.y + p.dy, klabel(i), 14, { italic: true, anchor: p.an, halo: 3, fill: acc ? ACCENT : '#000' }).opacity(op);
    txt(g, p.x + p.dx, p.y + p.dy + 11.5, String(S.keys[i]), 7.5, { anchor: p.an, fill: '#7a7a7a', family: SANS, halo: 2.5 }).opacity(op);
    (function (i, info) {
      c.on('mousemove', function (e) {
        showTooltip(klabel(i).replace(/[\u2080-\u2089]/g, function (d) { return String(SUB.indexOf(d)); }) + ' = ' + S.keys[i] + (info ? '  \u2192 slot ' + info.slot : '  (not stored)'), e);
      }).on('mouseleave', hideTooltip).on('click', function (e) {
        e.stopPropagation();
        if (info) setHighlight(S.highlight === info.slot ? null : info.slot);
      });
    })(i, info);
  }
}
function drawTable(g) {
  var sh = slotH();
  txt(g, TX + TW / 2, 26, 'T', 19, { italic: true });
  for (var i = 0; i < S.m; i++) {
    var y = slotY(i), occ = S.chains[i].length > 0, o = slotOp(i), acc = isAccent(i);
    var r = g.rect(TW, sh).move(TX, y)
      .fill(acc ? '#fbdcbf' : (occ ? '#efefef' : '#8f8f8f'))
      .stroke({ color: acc ? ACCENT : '#000', width: acc ? 2.4 : 1.4 }).opacity(o).css('cursor', 'pointer');
    if (!occ) {
      g.line(TX + TW * 0.30, y + sh * 0.76, TX + TW * 0.70, y + sh * 0.24).stroke({ color: '#111', width: 1.4 }).opacity(o).attr('pointer-events', 'none');
    } else {
      g.line(TX + TW * 0.38, y + sh / 2, TX + TW, y + sh / 2).stroke({ color: acc ? ACCENT : '#000', width: acc ? 1.8 : 1.4 }).opacity(o).attr('pointer-events', 'none');
    }
    txt(g, TX + 9, y + sh / 2, i, Math.min(9, sh * 0.42), { fill: occ ? '#6a6a6a' : '#ededed', family: SANS }).opacity(o);
    (function (i, occ) {
      r.on('mousemove', function (e) { showTooltip('slot ' + i + ' \u2014 ' + (occ ? 'chain of ' + S.chains[i].length + ' key(s)' : 'NIL (empty)'), e); })
        .on('mouseleave', hideTooltip)
        .on('click', function (e) {
          e.stopPropagation();
          var on = S.highlight !== i; setHighlight(on ? i : null);
          if (on && occ) {
            var names = S.chains[i].map(function (n) { return n.label + '=' + n.value; }).join(' \u2192 ');
            showPopup('Slot ' + i + ' \u2014 chain of ' + S.chains[i].length,
              'Every key shown in orange hashes to this one slot, so they collide. Chaining resolves that by threading them into a single doubly linked list: ' + names + '. A search for any of them walks exactly this list, so its cost is the chain length, not the table size.');
          } else if (on) {
            showPopup('Slot ' + i + ' \u2014 NIL', 'No key hashes here, so the slot holds NIL (drawn as a gray box with a slash). Empty slots are wasted space: with a good hash function they are few, with a bad one they are most of the table.');
          } else hidePopup();
        });
    })(i, occ);
  }
}
function drawChains(g) {
  var sh = slotH(), maxL = 1, i;
  for (i = 0; i < S.m; i++) maxL = Math.max(maxL, S.chains[i].length);
  var show = Math.min(maxL, 6);
  var nodeW = Math.max(48, Math.min(112, AVW / (show * 1.36 - 0.36)));
  var gap = nodeW * 0.36, pitch = nodeW + gap, c1 = nodeW * 0.27, c2 = nodeW * 0.46;
  var h = Math.max(14, Math.min(30, sh * 0.74));
  for (i = 0; i < S.m; i++) {
    var ch = S.chains[i]; if (!ch.length) continue;
    var yc = slotY(i) + sh / 2, o = slotOp(i), acc = isAccent(i), col = acc ? ACCENT : '#000';
    arrow(g, TX + TW + 1, yc, CX0 - 3, yc, col, acc ? 1.9 : 1.3, o);
    var n = Math.min(ch.length, show);
    for (var j = 0; j < n; j++) {
      var x = CX0 + j * pitch, y = yc - h / 2;
      var isNew = (S.highlight === null && S.flashSlot === i && S.flashK >= 0 && j === 0);
      var nr = g.rect(nodeW, h).move(x, y)
        .fill(acc ? '#fde3c9' : (isNew ? '#ffeccd' : '#e4e4e4'))
        .stroke({ color: (acc || isNew) ? ACCENT : '#000', width: (acc || isNew) ? 2 : 1.2 })
        .opacity(o).css('cursor', 'pointer');
      g.line(x + c1, y, x + c1, y + h).stroke({ color: '#000', width: 1 }).opacity(o).attr('pointer-events', 'none');
      g.line(x + c1 + c2, y, x + c1 + c2, y + h).stroke({ color: '#000', width: 1 }).opacity(o).attr('pointer-events', 'none');
      txt(g, x + c1 + c2 / 2, yc, ch[j].label, Math.min(13, c2 * 0.55, h * 0.62), { italic: true }).opacity(o);
      if (j === 0) g.line(x + 3.5, y + h - 3.5, x + c1 - 3.5, y + 3.5).stroke({ color: '#111', width: 1.1 }).opacity(o).attr('pointer-events', 'none');
      if (j === ch.length - 1) g.line(x + c1 + c2 + 3.5, y + h - 3.5, x + nodeW - 3.5, y + 3.5).stroke({ color: '#111', width: 1.1 }).opacity(o).attr('pointer-events', 'none');
      if (j < n - 1) {
        arrow(g, x + c1 + c2 + 4, yc - h * 0.24, x + pitch - 2, yc - h * 0.24, col, acc ? 1.6 : 1.1, o);
        arrow(g, x + pitch + c1 - 4, yc + h * 0.24, x + nodeW + 2, yc + h * 0.24, col, acc ? 1.6 : 1.1, o);
      }
      (function (node, slot) {
        nr.on('mousemove', function (e) { showTooltip(node.label + ' = ' + node.value + '  \u2014 slot ' + slot, e); })
          .on('mouseleave', hideTooltip)
          .on('click', function (e) { e.stopPropagation(); setHighlight(S.highlight === slot ? null : slot); });
      })(ch[j], i);
    }
    var endX = CX0 + (n - 1) * pitch + nodeW;
    if (ch.length > show) txt(g, endX + 8, yc, '+' + (ch.length - show) + ' more', Math.min(10, h * 0.5), { anchor: 'start', fill: '#555', family: SANS }).opacity(o);
    else txt(g, endX + 8, yc, '\u00d7' + ch.length, Math.min(9.5, h * 0.46), { anchor: 'start', fill: '#8a8a8a', family: SANS }).opacity(o);
  }
}
function drawFooter(g) {
  var n = 0;
  for (var i = 0; i < S.chains.length; i++) n += S.chains[i].length;
  txt(g, TX + TW / 2, 470, '\u03b1 = n/m = ' + n + '/' + S.m + ' = ' + (n / S.m).toFixed(2), 11.5, { fill: '#333', halo: 3 });
  txt(g, 1172, 480, 'slash = NIL   \u00b7   dark slot = empty', 9, { anchor: 'end', fill: '#9a9a9a', family: SANS });
}
function render() {
  figScene.clear();
  var g = figScene;
  g.rect(FW, FH).fill('#ffffff').on('click', function () { setHighlight(null); hidePopup(); });
  drawUniverse(g);
  var map = keySlotMap();
  drawArrows(g);
  drawDots(g, map);
  drawTable(g);
  drawChains(g);
  drawFooter(g);
}
function setHighlight(i) { S.highlight = i; render(); }

/* ---------- default / preview state ---------- */
function defaultChains() {
  var m = S.m, ch = [], i;
  for (i = 0; i < m; i++) ch.push([]);
  if (m === 10 && S.keys.length >= 8) {
    var ord = [[1, [0, 3]], [5, [4, 1, 6]], [7, [2]], [8, [7, 5]]], ok = true;
    ord.forEach(function (p) { p[1].forEach(function (k) { if (((S.keys[k] % 10) + 10) % 10 !== p[0]) ok = false; }); });
    if (ok) {
      ord.forEach(function (p) {
        ch[p[0]] = p[1].map(function (k) { return { label: klabel(k), value: S.keys[k], kIdx: k }; });
      });
      return ch;
    }
  }
  for (i = 0; i < S.keys.length; i++) {
    var s = ((S.keys[i] % m) + m) % m;
    if (!isFinite(s)) continue;
    ch[s].unshift({ label: klabel(i), value: S.keys[i], kIdx: i });
  }
  return ch;
}
function parseKeys() {
  var raw = document.getElementById('hashCodeInput').value;
  var parts = String(raw).split(/[\s,;]+/), out = [];
  for (var i = 0; i < parts.length; i++) { if (!parts[i]) continue; var v = Number(parts[i]); if (isFinite(v)) out.push(v); }
  return out.length ? out : [11, 25, 17, 41, 15, 28, 35, 18];
}
function resetFigure() {
  S.keys = parseKeys(); S.chains = defaultChains(); S.highlight = null; S.flashSlot = -1; S.flashK = -1; S.bad = null;
  FR.frames = []; FR.i = 0; stopPlay();
  document.getElementById('frameCounter').textContent = '0 of 0';
  document.getElementById('frameCaption').textContent = '';
  document.getElementById('runLog').textContent = '';
  setStatus('#666', 'not run \u2014 showing h(k) = k mod m');
  render();
}
function setStatus(color, text) {
  var el = document.getElementById('runStatus');
  el.style.color = color; el.textContent = text;
}

/* ---------- controls ---------- */
function update_tableSize(v) {
  S.m = v; S.keys = parseKeys(); S.chains = defaultChains();
  S.highlight = null; S.flashSlot = -1; S.flashK = -1; S.bad = null;
  FR.frames = []; FR.i = 0; stopPlay();
  document.getElementById('frameCounter').textContent = '0 of 0';
  document.getElementById('frameCaption').textContent = '';
  setStatus('#666', 'preview: h(k) = k mod m \u2014 press Run');
  render();
}
function setSlider(v) {
  var el = document.getElementById('tableSizeInput');
  el.value = v; document.getElementById('tableSizeVal').value = v;
  update_tableSize(v);
}

var SAMPLES = {
  sample: 'function hashAll(keys) {\n  for (const k of keys) {\n    const i = k % m();        // division method\n    note("h(" + k + ") = " + i);\n    insert(k, i);\n  }\n}',
  buggy: 'function hashAll(keys) {\n  for (const k of keys) {\n    // BUG: table size hardcoded as 10 instead of m(),\n    // so slots go out of range (or are never used) when m changes\n    const i = k % 10;\n    insert(k, i);\n  }\n}',
  bad: 'function hashAll(keys) {\n  // A legal but terrible hash: everything to slot 0\n  for (const k of keys) {\n    insert(k, 0);\n  }\n}',
  blank: 'function hashAll(keys) {\n  // your hash function here\n  // available: m(), insert(k, i), chainLength(i), note(msg)\n  for (const k of keys) {\n\n  }\n}'
};
function setTab(name) {
  document.getElementById('hashCodeCode').value = SAMPLES[name] || SAMPLES.blank;
  ['sample', 'buggy', 'bad', 'blank'].forEach(function (t) {
    var b = document.getElementById('tab-' + t); if (b) b.className = (t === name ? 'active' : '');
  });
}

/* ---------- sandboxed runner ---------- */
var WORKER_SRC = [
  'self.onmessage = function(ev){',
  '  var d = ev.data, m = d.m, keys = d.keys, code = d.code;',
  '  var chains = []; for (var i=0;i<m;i++) chains.push([]);',
  '  var frames = [], ops = 0, t0 = Date.now(), used = [];',
  '  function copy(){ var c=[]; for(var a=0;a<chains.length;a++){ var r=[]; for(var b=0;b<chains[a].length;b++){ var n=chains[a][b]; r.push({label:n.label,value:n.value,kIdx:n.kIdx}); } c.push(r);} return c; }',
  '  function push(kind, idx, msg, kIdx){ frames.push({kind:kind,state:{m:m,chains:copy()},indices:idx,message:msg,kIdx:(kIdx==null?-1:kIdx)}); if(frames.length>300) throw new Error("__CAP__frame cap (300) reached \u2014 is your loop terminating?"); }',
  '  function guard(){ ops++; if(ops>3000) throw new Error("__CAP__operation cap (3000) reached"); if(Date.now()-t0>1500) throw new Error("__CAP__time limit exceeded \u2014 infinite loop?"); }',
  '  function labelFor(k){ for(var i=0;i<keys.length;i++){ if(!used[i] && keys[i]===k){ used[i]=1; return {label:d.labels[i], kIdx:i}; } } return {label:String(k), kIdx:-1}; }',
  '  var api = {',
