  '      if(ii<0||ii>=m) throw new Error("insert("+kk+", "+ii+"): slot out of range 0.."+(m-1)+"   (m() = "+m+")");',
  '      var L=labelFor(kk); chains[ii].unshift({label:L.label,value:kk,kIdx:L.kIdx});',
  '      push("insert",[ii], L.label+" = "+kk+"  \u2192  slot "+ii+"   (chain length now "+chains[ii].length+")", L.kIdx);',
  '      return ii; }',
  '  };',
  '  if (Object.freeze) Object.freeze(api);',
  '  var entry=null, err=null;',
  '  try {',
  '    var factory = new Function("api", "\'use strict\'; var m=api.m, insert=api.insert, chainLength=api.chainLength, note=api.note;\\n" + code + "\\nreturn (typeof hashAll===\'function\') ? hashAll : null;");',
  '    entry = factory(api);',
  '  } catch(e){ err = "Syntax error: " + ((e&&e.message)?e.message:e); }',
  '  if(!err && !entry) err = "entry point hashAll(keys) not found \u2014 define  function hashAll(keys) { ... }";',
  '  if(!err){ try { entry(keys.slice()); } catch(e){ var msg=(e&&e.message)?e.message:String(e); if(msg.indexOf("__CAP__")===0) msg=msg.slice(7); err = msg; } }',
  '  if(err){ try{ push("error", [], "\u26d4 " + err, -1); }catch(e2){} }',
  '  else { push("done", [], "done \u2014 " + keys.length + " key(s) processed", -1); }',
  '  self.postMessage({frames:frames, error:err});',
  '};'
].join('\n');

function evaluateRun(finalChains, err) {
  if (err) return { cls: '#c62828', text: '\u26d4 error \u2014 see caption', bad: [] };
  var seen = {}, extra = 0, i, j;
  for (i = 0; i < finalChains.length; i++) for (j = 0; j < finalChains[i].length; j++) {
    var n = finalChains[i][j];
    if (n.kIdx >= 0) seen[n.kIdx] = (seen[n.kIdx] || 0) + 1; else extra++;
  }
  var missing = [], dup = [];
  for (i = 0; i < S.keys.length; i++) if (!seen[i]) missing.push(i);
  for (var k in seen) if (seen[k] > 1) dup.push(+k);
  if (missing.length) return { cls: '#c62828', text: '\u2717 not stored: ' + missing.map(function (i) { return klabel(i); }).join(', '), bad: missing };
  if (dup.length) return { cls: '#c62828', text: '\u2717 stored twice: ' + dup.map(function (i) { return klabel(i); }).join(', '), bad: dup };
  if (extra) return { cls: '#c62828', text: '\u2717 ' + extra + ' key(s) inserted that are not in the input', bad: [] };
  var occ = 0, maxL = 0;
  for (i = 0; i < finalChains.length; i++) { if (finalChains[i].length) occ++; maxL = Math.max(maxL, finalChains[i].length); }
  if (finalChains.length > 1 && occ === 1 && S.keys.length > 1)
    return { cls: '#b26a00', text: '\u2713 stored \u2014 but all ' + S.keys.length + ' in ONE chain: \u0398(n) search', bad: [] };
  return { cls: '#1b7a30', text: '\u2713 correct \u2014 ' + S.keys.length + ' keys, longest chain ' + maxL, bad: [] };
}

function trigger_hashCode(autoplay, cb) {
  if (FR.running) return;
  autoplay = (autoplay === undefined) ? true : autoplay;
  stopPlay();
  S.keys = parseKeys();
  S.m = +document.getElementById('tableSizeInput').value;
  S.highlight = null; S.bad = null;
  var code = document.getElementById('hashCodeCode').value;
  var labels = S.keys.map(function (v, i) { return klabel(i); });
  var btn = document.getElementById('runBtn');
  FR.running = true; btn.disabled = true;
  setStatus('#1565c0', 'running\u2026');
  var url = null, w = null, done = false, timer = 0;
  function finish() { if (timer) clearTimeout(timer); FR.running = false; btn.disabled = false; if (url) URL.revokeObjectURL(url); }
  try {
    url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
    w = new Worker(url);
  } catch (e) {
    finish(); setStatus('#c62828', '\u26d4 sandbox unavailable: ' + e.message); return;
  }
  timer = setTimeout(function () {
    if (done) return; done = true; w.terminate(); finish();
    FR.frames = [{ kind: 'error', state: { m: S.m, chains: defaultChainsEmpty(S.m) }, indices: [], message: '\u26d4 timed out (2 s) \u2014 worker terminated. Infinite loop?', kIdx: -1 }];
    setFrame(0); setStatus('#c62828', '\u26d4 timeout');
  }, 2000);
  w.onerror = function (e) {
    if (done) return; done = true; w.terminate(); finish();
    setStatus('#c62828', '\u26d4 ' + (e.message || 'worker error'));
  };
  w.onmessage = function (ev) {
    if (done) return; done = true; w.terminate(); finish();
    var res = ev.data;
    FR.frames = res.frames || [];
    if (!FR.frames.length) { setStatus('#c62828', '\u26d4 no frames produced'); return; }
    var last = FR.frames[FR.frames.length - 1].state.chains;
    var verdict = evaluateRun(last, res.error);
    setStatus(verdict.cls, verdict.text);
    S.bad = verdict.bad && verdict.bad.length ? verdict.bad : null;
    if (autoplay) { setFrame(0); pbPlay(); } else { setFrame(FR.frames.length - 1); }
    if (typeof cb === 'function') cb();
  };
  w.postMessage({ m: S.m, keys: S.keys.slice(), code: code, labels: labels });
}
function defaultChainsEmpty(m) { var c = []; for (var i = 0; i < m; i++) c.push([]); return c; }

/* ---------- playback ---------- */
function setFrame(i) {
  if (!FR.frames.length) return;
  FR.i = Math.max(0, Math.min(FR.frames.length - 1, i));
  var f = FR.frames[FR.i];
  S.m = f.state.m; S.chains = f.state.chains;
  S.flashSlot = (f.indices && f.indices.length) ? f.indices[0] : -1;
  S.flashK = (f.kIdx == null ? -1 : f.kIdx);
  document.getElementById('frameCounter').textContent = (FR.i + 1) + ' of ' + FR.frames.length;
  document.getElementById('frameCaption').textContent = f.message || '';
  var lines = [];
  for (var j = 0; j <= FR.i; j++) lines.push((j + 1) + '. ' + FR.frames[j].message);
  var lg = document.getElementById('runLog');
  lg.textContent = lines.join('\n'); lg.scrollTop = lg.scrollHeight;
  render();
}
function stopPlay() {
  if (FR.timer) { clearInterval(FR.timer); FR.timer = 0; }
  FR.playing = false;
  var b = document.getElementById('playBtn'); if (b) b.textContent = '\u25b6';
}
function pbPlay() {
  if (!FR.frames.length) return;
  if (FR.playing) { stopPlay(); return; }
  if (FR.i >= FR.frames.length - 1) setFrame(0);
  FR.playing = true; document.getElementById('playBtn').textContent = '\u23f8';
  var sp = +document.getElementById('speedInput').value || 1;
  FR.timer = setInterval(function () {
    if (FR.i >= FR.frames.length - 1) { stopPlay(); return; }
    setFrame(FR.i + 1);
  }, Math.max(90, 750 / sp));
}
function pbFirst() { stopPlay(); setFrame(0); }
function pbPrev() { stopPlay(); setFrame(FR.i - 1); }
function pbNext() { stopPlay(); setFrame(FR.i + 1); }

/* ---------- demo steps ---------- */
var STEPS = [
  {
