  var h = Math.max(14, Math.min(30, sh * 0.74));
  for (i = 0; i < S.m; i++) {
    var ch = S.chains[i]; if (!ch.length) continue;
    var yc = slotY(i) + sh / 2, o = slotOp(i), acc = isAccent(i), col = acc ? ACCENT : '#000';
    arrow(g, TX + TW + 1, yc, CX0 - 3, yc, col, acc ? 1.9 : 1.3, o);
    var n = Math.min(ch.length, show);
    for (var j = 0; j < n; j++) {
      var x = CX0 + j * pitch, y = yc - h / 2;
      var isNew = (S.highlight === null && S.flashSlot === i && S.flashK >= 0 && j === 0);
      var nr = g.rect(nodeW, h).move(x, y)
        .fill(acc ? '#fde3c9' : (isNew ? '#ffeccd' : '#e4e4e4'))
        .stroke({ color: (acc || isNew) ? ACCENT : '#000', width: (acc || isNew) ? 2 : 1.2 })
        .opacity(o).css('cursor', 'pointer');
      g.line(x + c1, y, x + c1, y + h).stroke({ color: '#000', width: 1 }).opacity(o).attr('pointer-events', 'none');
      g.line(x + c1 + c2, y, x + c1 + c2, y + h).stroke({ color: '#000', width: 1 }).opacity(o).attr('pointer-events', 'none');
      txt(g, x + c1 + c2 / 2, yc, ch[j].label, Math.min(13, c2 * 0.55, h * 0.62), { italic: true }).opacity(o);
      if (j === 0) g.line(x + 3.5, y + h - 3.5, x + c1 - 3.5, y + 3.5).stroke({ color: '#111', width: 1.1 }).opacity(o).attr('pointer-events', 'none');
      if (j === ch.length - 1) g.line(x + c1 + c2 + 3.5, y + h - 3.5, x + nodeW - 3.5, y + 3.5).stroke({ color: '#111', width: 1.1 }).opacity(o).attr('pointer-events', 'none');
      if (j < n - 1) {
        arrow(g, x + c1 + c2 + 4, yc - h * 0.24, x + pitch - 2, yc - h * 0.24, col, acc ? 1.6 : 1.1, o);
        arrow(g, x + pitch + c1 - 4, yc + h * 0.24, x + nodeW + 2, yc + h * 0.24, col, acc ? 1.6 : 1.1, o);
      }
      (function (node, slot) {
        nr.on('mousemove', function (e) { showTooltip(node.label + ' = ' + node.value + '  \u2014 slot ' + slot, e); })
          .on('mouseleave', hideTooltip)
          .on('click', function (e) { e.stopPropagation(); setHighlight(S.highlight === slot ? null : slot); });
      })(ch[j], i);
    }
    var endX = CX0 + (n - 1) * pitch + nodeW;
    if (ch.length > show) txt(g, endX + 8, yc, '+' + (ch.length - show) + ' more', Math.min(10, h * 0.5), { anchor: 'start', fill: '#555', family: SANS }).opacity(o);
    else txt(g, endX + 8, yc, '\u00d7' + ch.length, Math.min(9.5, h * 0.46), { anchor: 'start', fill: '#8a8a8a', family: SANS }).opacity(o);
  }
}
function drawFooter(g) {
  var n = 0;
  for (var i = 0; i < S.chains.length; i++) n += S.chains[i].length;
  txt(g, TX + TW / 2, 470, '\u03b1 = n/m = ' + n + '/' + S.m + ' = ' + (n / S.m).toFixed(2), 11.5, { fill: '#333', halo: 3 });
  txt(g, 1172, 480, 'slash = NIL   \u00b7   dark slot = empty', 9, { anchor: 'end', fill: '#9a9a9a', family: SANS });
}
function render() {
  figScene.clear();
  var g = figScene;
  g.rect(FW, FH).fill('#ffffff').on('click', function () { setHighlight(null); hidePopup(); });
  drawUniverse(g);
  var map = keySlotMap();
  drawArrows(g);
  drawDots(g, map);
  drawTable(g);
  drawChains(g);
  drawFooter(g);
}
function setHighlight(i) { S.highlight = i; render(); }

/* ---------- default / preview state ---------- */
function defaultChains() {
  var m = S.m, ch = [], i;
  for (i = 0; i < m; i++) ch.push([]);
  if (m === 10 && S.keys.length >= 8) {
    var ord = [[1, [0, 3]], [5, [4, 1, 6]], [7, [2]], [8, [7, 5]]], ok = true;
    ord.forEach(function (p) { p[1].forEach(function (k) { if (((S.keys[k] % 10) + 10) % 10 !== p[0]) ok = false; }); });
    if (ok) {
      ord.forEach(function (p) {
        ch[p[0]] = p[1].map(function (k) { return { label: klabel(k), value: S.keys[k], kIdx: k }; });
      });
      return ch;
    }
  }
  for (i = 0; i < S.keys.length; i++) {
    var s = ((S.keys[i] % m) + m) % m;
    if (!isFinite(s)) continue;
    ch[s].unshift({ label: klabel(i), value: S.keys[i], kIdx: i });
  }
  return ch;
}
function parseKeys() {
  var raw = document.getElementById('hashCodeInput').value;
  var parts = String(raw).split(/[\s,;]+/), out = [];
  for (var i = 0; i < parts.length; i++) { if (!parts[i]) continue; var v = Number(parts[i]); if (isFinite(v)) out.push(v); }
  return out.length ? out : [11, 25, 17, 41, 15, 28, 35, 18];
}
function resetFigure() {
  S.keys = parseKeys(); S.chains = defaultChains(); S.highlight = null; S.flashSlot = -1; S.flashK = -1; S.bad = null;
  FR.frames = []; FR.i = 0; stopPlay();
  document.getElementById('frameCounter').textContent = '0 of 0';
  document.getElementById('frameCaption').textContent = '';
  document.getElementById('runLog').textContent = '';
  setStatus('#666', 'not run \u2014 showing h(k) = k mod m');
  render();
}
function setStatus(color, text) {
  var el = document.getElementById('runStatus');
  el.style.color = color; el.textContent = text;
}

/* ---------- controls ---------- */
function update_tableSize(v) {
  S.m = v; S.keys = parseKeys(); S.chains = defaultChains();
  S.highlight = null; S.flashSlot = -1; S.flashK = -1; S.bad = null;
  FR.frames = []; FR.i = 0; stopPlay();
  document.getElementById('frameCounter').textContent = '0 of 0';
  document.getElementById('frameCaption').textContent = '';
  setStatus('#666', 'preview: h(k) = k mod m \u2014 press Run');
  render();
}
function setSlider(v) {
  var el = document.getElementById('tableSizeInput');
  el.value = v; document.getElementById('tableSizeVal').value = v;
  update_tableSize(v);
}

var SAMPLES = {
  sample: 'function hashAll(keys) {\n  for (const k of keys) {\n    const i = k % m();        // division method\n    note("h(" + k + ") = " + i);\n    insert(k, i);\n  }\n}',
  buggy: 'function hashAll(keys) {\n  for (const k of keys) {\n    // BUG: table size hardcoded as 10 instead of m(),\n    // so slots go out of range (or are never used) when m changes\n    const i = k % 10;\n    insert(k, i);\n  }\n}',
  bad: 'function hashAll(keys) {\n  // A legal but terrible hash: everything to slot 0\n  for (const k of keys) {\n    insert(k, 0);\n  }\n}',
  blank: 'function hashAll(keys) {\n  // your hash function here\n  // available: m(), insert(k, i), chainLength(i), note(msg)\n  for (const k of keys) {\n\n  }\n}'
};
function setTab(name) {
  document.getElementById('hashCodeCode').value = SAMPLES[name] || SAMPLES.blank;
  ['sample', 'buggy', 'bad', 'blank'].forEach(function (t) {
    var b = document.getElementById('tab-' + t); if (b) b.className = (t === name ? 'active' : '');
  });
}

/* ---------- sandboxed runner ---------- */
var WORKER_SRC = [
  'self.onmessage = function(ev){',
  '  var d = ev.data, m = d.m, keys = d.keys, code = d.code;',
  '  var chains = []; for (var i=0;i<m;i++) chains.push([]);',
  '  var frames = [], ops = 0, t0 = Date.now(), used = [];',
  '  function copy(){ var c=[]; for(var a=0;a<chains.length;a++){ var r=[]; for(var b=0;b<chains[a].length;b++){ var n=chains[a][b]; r.push({label:n.label,value:n.value,kIdx:n.kIdx}); } c.push(r);} return c; }',
  '  function push(kind, idx, msg, kIdx){ frames.push({kind:kind,state:{m:m,chains:copy()},indices:idx,message:msg,kIdx:(kIdx==null?-1:kIdx)}); if(frames.length>300) throw new Error("__CAP__frame cap (300) reached \u2014 is your loop terminating?"); }',
  '  function guard(){ ops++; if(ops>3000) throw new Error("__CAP__operation cap (3000) reached"); if(Date.now()-t0>1500) throw new Error("__CAP__time limit exceeded \u2014 infinite loop?"); }',
  '  function labelFor(k){ for(var i=0;i<keys.length;i++){ if(!used[i] && keys[i]===k){ used[i]=1; return {label:d.labels[i], kIdx:i}; } } return {label:String(k), kIdx:-1}; }',
  '  var api = {',
  '    m: function(){ guard(); return m; },',
  '    chainLength: function(i){ guard(); var ii=Number(i); if(!isFinite(ii)||Math.floor(ii)!==ii||ii<0||ii>=m) throw new Error("chainLength("+i+"): slot out of range 0.."+(m-1)); return chains[ii].length; },',
  '    note: function(msg){ guard(); push("note", [], String(msg), -1); },',
  '    insert: function(k, i){ guard();',
  '      var kk=Number(k); if(!isFinite(kk)) throw new Error("insert("+k+", "+i+"): key must be a number");',
  '      var ii=Number(i); if(!isFinite(ii)||Math.floor(ii)!==ii) throw new Error("insert("+kk+", "+i+"): slot must be an integer");',
  '      if(ii<0||ii>=m) throw new Error("insert("+kk+", "+ii+"): slot out of range 0.."+(m-1)+"   (m() = "+m+")");',
  '      var L=labelFor(kk); chains[ii].unshift({label:L.label,value:kk,kIdx:L.kIdx});',
  '      push("insert",[ii], L.label+" = "+kk+"  \u2192  slot "+ii+"   (chain length now "+chains[ii].length+")", L.kIdx);',
  '      return ii; }',
  '  };',
  '  if (Object.freeze) Object.freeze(api);',
  '  var entry=null, err=null;',
  '  try {',
  '    var factory = new Function("api", "\'use strict\'; var m=api.m, insert=api.insert, chainLength=api.chainLength, note=api.note;\\n" + code + "\\nreturn (typeof hashAll===\'function\') ? hashAll : null;");',
  '    entry = factory(api);',
  '  } catch(e){ err = "Syntax error: " + ((e&&e.message)?e.message:e); }',
  '  if(!err && !entry) err = "entry point hashAll(keys) not found \u2014 define  function hashAll(keys) { ... }";',
  '  if(!err){ try { entry(keys.slice()); } catch(e){ var msg=(e&&e.message)?e.message:String(e); if(msg.indexOf("__CAP__")===0) msg=msg.slice(7); err = msg; } }',
  '  if(err){ try{ push("error", [], "\u26d4 " + err, -1); }catch(e2){} }',
  '  else { push("done", [], "done \u2014 " + keys.length + " key(s) processed", -1); }',
  '  self.postMessage({frames:frames, error:err});',
  '};'
].join('\n');

function evaluateRun(finalChains, err) {
  if (err) return { cls: '#c62828', text: '\u26d4 error \u2014 see caption', bad: [] };
  var seen = {}, extra = 0, i, j;
  for (i = 0; i < finalChains.length; i++) for (j = 0; j < finalChains[i].length; j++) {
    var n = finalChains[i][j];
    if (n.kIdx >= 0) seen[n.kIdx] = (seen[n.kIdx] || 0) + 1; else extra++;
  }
  var missing = [], dup = [];
  for (i = 0; i < S.keys.length; i++) if (!seen[i]) missing.push(i);
  for (var k in seen) if (seen[k] > 1) dup.push(+k);
  if (missing.length) return { cls: '#c62828', text: '\u2717 not stored: ' + missing.map(function (i) { return klabel(i); }).join(', '), bad: missing };
  if (dup.length) return { cls: '#c62828', text: '\u2717 stored twice: ' + dup.map(function (i) { return klabel(i); }).join(', '), bad: dup };
  if (extra) return { cls: '#c62828', text: '\u2717 ' + extra + ' key(s) inserted that are not in the input', bad: [] };
  var occ = 0, maxL = 0;
  for (i = 0; i < finalChains.length; i++) { if (finalChains[i].length) occ++; maxL = Math.max(maxL, finalChains[i].length); }
  if (finalChains.length > 1 && occ === 1 && S.keys.length > 1)
    return { cls: '#b26a00', text: '\u2713 stored \u2014 but all ' + S.keys.length + ' in ONE chain: \u0398(n) search', bad: [] };
  return { cls: '#1b7a30', text: '\u2713 correct \u2014 ' + S.keys.length + ' keys, longest chain ' + maxL, bad: [] };
}

function trigger_hashCode(autoplay, cb) {
  if (FR.running) return;
  autoplay = (autoplay === undefined) ? true : autoplay;
  stopPlay();
  S.keys = parseKeys();
  S.m = +document.getElementById('tableSizeInput').value;
  S.highlight = null; S.bad = null;
  var code = document.getElementById('hashCodeCode').value;
  var labels = S.keys.map(function (v, i) { return klabel(i); });
  var btn = document.getElementById('runBtn');
  FR.running = true; btn.disabled = true;
  setStatus('#1565c0', 'running\u2026');
  var url = null, w = null, done = false, timer = 0;
  function finish() { if (timer) clearTimeout(timer); FR.running = false; btn.disabled = false; if (url) URL.revokeObjectURL(url); }
  try {
    url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
    w = new Worker(url);
  } catch (e) {
    finish(); setStatus('#c62828', '\u26d4 sandbox unavailable: ' + e.message); return;
  }
  timer = setTimeout(function () {
    if (done) return; done = true; w.terminate(); finish();
    FR.frames = [{ kind: 'error', state: { m: S.m, chains: defaultChainsEmpty(S.m) }, indices: [], message: '\u26d4 timed out (2 s) \u2014 worker terminated. Infinite loop?', kIdx: -1 }];
    setFrame(0); setStatus('#c62828', '\u26d4 timeout');
  }, 2000);
  w.onerror = function (e) {
    if (done) return; done = true; w.terminate(); finish();
    setStatus('#c62828', '\u26d4 ' + (e.message || 'worker error'));
  };
  w.onmessage = function (ev) {
    if (done) return; done = true; w.terminate(); finish();
    var res = ev.data;
    FR.frames = res.frames || [];
    if (!FR.frames.length) { setStatus('#c62828', '\u26d4 no frames produced'); return; }
    var last = FR.frames[FR.frames.length - 1].state.chains;
    var verdict = evaluateRun(last, res.error);
    setStatus(verdict.cls, verdict.text);
    S.bad = verdict.bad && verdict.bad.length ? verdict.bad : null;
    if (autoplay) { setFrame(0); pbPlay(); } else { setFrame(FR.frames.length - 1); }
    if (typeof cb === 'function') cb();
  };
  w.postMessage({ m: S.m, keys: S.keys.slice(), code: code, labels: labels });
}
function defaultChainsEmpty(m) { var c = []; for (var i = 0; i < m; i++) c.push([]); return c; }

/* ---------- playback ---------- */
function setFrame(i) {
  if (!FR.frames.length) return;
  FR.i = Math.max(0, Math.min(FR.frames.length - 1, i));
  var f = FR.frames[FR.i];
  S.m = f.state.m; S.chains = f.state.chains;
  S.flashSlot = (f.indices && f.indices.length) ? f.indices[0] : -1;
  S.flashK = (f.kIdx == null ? -1 : f.kIdx);
  document.getElementById('frameCounter').textContent = (FR.i + 1) + ' of ' + FR.frames.length;
  document.getElementById('frameCaption').textContent = f.message || '';
  var lines = [];
  for (var j = 0; j <= FR.i; j++) lines.push((j + 1) + '. ' + FR.frames[j].message);
  var lg = document.getElementById('runLog');
  lg.textContent = lines.join('\n'); lg.scrollTop = lg.scrollHeight;
  render();
}
function stopPlay() {
  if (FR.timer) { clearInterval(FR.timer); FR.timer = 0; }
  FR.playing = false;
  var b = document.getElementById('playBtn'); if (b) b.textContent = '\u25b6';
}
function pbPlay() {
  if (!FR.frames.length) return;
  if (FR.playing) { stopPlay(); return; }
  if (FR.i >= FR.frames.length - 1) setFrame(0);
  FR.playing = true; document.getElementById('playBtn').textContent = '\u23f8';
  var sp = +document.getElementById('speedInput').value || 1;
  FR.timer = setInterval(function () {
    if (FR.i >= FR.frames.length - 1) { stopPlay(); return; }
    setFrame(FR.i + 1);
  }, Math.max(90, 750 / sp));
}
function pbFirst() { stopPlay(); setFrame(0); }
function pbPrev() { stopPlay(); setFrame(FR.i - 1); }
function pbNext() { stopPlay(); setFrame(FR.i + 1); }

/* ---------- demo steps ---------- */
var STEPS = [
  {
    t: 'The universe and the actual keys',
    n: 'U holds every key that could ever occur; only the handful in K are really stored. The table T has far fewer slots than |U|, so some keys must share.',
    go: function () { setSlider(10); resetFigure(); }
  },
  {
    t: 'Run h(k) = k mod m',
    n: 'The sample code walks the keys and calls insert(k, k % m()). Watch each arrow get drawn one at a time: k\u2081 and k\u2084 both land in slot 1, so the second one is simply prepended in front of the first.',
    go: function () { setSlider(10); setTab('sample'); trigger_hashCode(true); }
  },
  {
    t: 'A collision is just a longer list',
    n: 'Slot 5 receives three keys and holds a chain of three nodes; slot 7 holds one; five slots stay NIL. Chaining never rejects a key \u2014 it only lengthens a list.',
    go: function () { setSlider(10); setTab('sample'); trigger_hashCode(false, function () { setHighlight(5); }); }
  },
  {
    t: 'Shrink the table',
    n: 'Drop m to 5 and re-run: the same eight keys crowd into fewer slots, chains grow and the load factor \u03b1 = n/m jumps \u2014 search time follows chain length, not table size.',
    go: function () { setSlider(5); setTab('sample'); trigger_hashCode(true); }
  },
  {
    t: 'A bad hash function',
    n: 'Load a hash that returns 0 for everything (or the Buggy tab at m \u2260 10): every key funnels into one slot and the hash table degenerates into a single linked list with \u0398(n) search. Then fix h and watch the chains flatten out again.',
    go: function () { setSlider(10); setTab('bad'); trigger_hashCode(true); }
  }
];
var stepIdx = 0;
function setStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[stepIdx];
  document.getElementById('demoNarration').innerHTML = '<b>' + s.t + '</b><br>' + s.n;
  document.getElementById('stepLabel').textContent = 'step ' + (stepIdx + 1) + ' / ' + STEPS.length;
  s.go();
}
function nextStep() { setStep(stepIdx + 1); }
function prevStep() { setStep(stepIdx - 1); }

/* ---------- init ---------- */
document.getElementById('hashCodeInput').addEventListener('input', function () {
  S.keys = parseKeys(); S.chains = defaultChains(); S.bad = null;
  FR.frames = []; FR.i = 0; stopPlay();
  document.getElementById('frameCounter').textContent = '0 of 0';
  setStatus('#666', 'keys changed \u2014 press Run');
  render();
});
setTab('sample');
S.keys = parseKeys();
S.chains = defaultChains();
setStatus('#666', 'not run \u2014 showing h(k) = k mod m');
setStep(0);
render();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
