  '    chainLength: function(i){ guard(); var ii=Number(i); if(!isFinite(ii)||Math.floor(ii)!==ii||ii<0||ii>=m) throw new Error("chainLength("+i+"): slot out of range 0.."+(m-1)); return chains[ii].length; },',
  '    note: function(msg){ guard(); push("note", [], String(msg), -1); },',
  '    insert: function(k, i){ guard();',
  '      var kk=Number(k); if(!isFinite(kk)) throw new Error("insert("+k+", "+i+"): key must be a number");',
  '      var ii=Number(i); if(!isFinite(ii)||Math.floor(ii)!==ii) throw new Error("insert("+kk+", "+i+"): slot must be an integer");',
  '      if(ii<0||ii>=m) throw new Error("insert("+kk+", "+ii+"): slot out of range 0.."+(m-1)+"   (m() = "+m+")");',
  '      var L=labelFor(kk); chains[ii].unshift({label:L.label,value:kk,kIdx:L.kIdx});',
  '      push("insert",[ii], L.label+" = "+kk+"  \u2192  slot "+ii+"   (chain length now "+chains[ii].length+")", L.kIdx);',
  '      return ii; }',
  '  };',
  '  if (Object.freeze) Object.freeze(api);',
  '  var entry=null, err=null;',
  '  try {',
  '    var factory = new Function("api", "\'use strict\'; var m=api.m, insert=api.insert, chainLength=api.chainLength, note=api.note;\\n" + code + "\\nreturn (typeof hashAll===\'function\') ? hashAll : null;");',
  '    entry = factory(api);',
  '  } catch(e){ err = "Syntax error: " + ((e&&e.message)?e.message:e); }',
  '  if(!err && !entry) err = "entry point hashAll(keys) not found \u2014 define  function hashAll(keys) { ... }";',
  '  if(!err){ try { entry(keys.slice()); } catch(e){ var msg=(e&&e.message)?e.message:String(e); if(msg.indexOf("__CAP__")===0) msg=msg.slice(7); err = msg; } }',
  '  if(err){ try{ push("error", [], "\u26d4 " + err, -1); }catch(e2){} }',
  '  else { push("done", [], "done \u2014 " + keys.length + " key(s) processed", -1); }',
  '  self.postMessage({frames:frames, error:err});',
  '};'
].join('\n');

function evaluateRun(finalChains, err) {
  if (err) return { cls: '#c62828', text: '\u26d4 error \u2014 see caption', bad: [] };
  var seen = {}, extra = 0, i, j;
  for (i = 0; i < finalChains.length; i++) for (j = 0; j < finalChains[i].length; j++) {
    var n = finalChains[i][j];
    if (n.kIdx >= 0) seen[n.kIdx] = (seen[n.kIdx] || 0) + 1; else extra++;
  }
  var missing = [], dup = [];
  for (i = 0; i < S.keys.length; i++) if (!seen[i]) missing.push(i);
  for (var k in seen) if (seen[k] > 1) dup.push(+k);
  if (missing.length) return { cls: '#c62828', text: '\u2717 not stored: ' + missing.map(function (i) { return plain(i); }).join(', '), bad: missing };
  if (dup.length) return { cls: '#c62828', text: '\u2717 stored twice: ' + dup.map(function (i) { return plain(i); }).join(', '), bad: dup };
  if (extra) return { cls: '#c62828', text: '\u2717 ' + extra + ' key(s) inserted that are not in the input', bad: [] };
  var occ = 0, maxL = 0;
  for (i = 0; i < finalChains.length; i++) { if (finalChains[i].length) occ++; maxL = Math.max(maxL, finalChains[i].length); }
  if (finalChains.length > 1 && occ === 1 && S.keys.length > 1)
    return { cls: '#b26a00', text: '\u2713 stored \u2014 but all ' + S.keys.length + ' in ONE chain: \u0398(n) search', bad: [] };
  return { cls: '#1b7a30', text: '\u2713 correct \u2014 ' + S.keys.length + ' keys, longest chain ' + maxL, bad: [] };
}

function trigger_hashCode(autoplay, cb) {
  if (FR.running) return;
  autoplay = (autoplay === undefined) ? true : autoplay;
  stopPlay();
  S.keys = parseKeys();
  S.m = +document.getElementById('tableSizeInput').value;
  S.highlight = null; S.bad = null;
  var code = document.getElementById('hashCodeCode').value;
  var labels = S.keys.map(function (v, i) { return klabel(i); });
  var btn = document.getElementById('runBtn');
  FR.running = true; btn.disabled = true;
  setStatus('#1565c0', 'running\u2026');
  var url = null, w = null, done = false, timer = 0;
  function finish() { if (timer) clearTimeout(timer); FR.running = false; btn.disabled = false; if (url) URL.revokeObjectURL(url); }
  try {
    url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
    w = new Worker(url);
  } catch (e) {
    finish(); setStatus('#c62828', '\u26d4 sandbox unavailable: ' + e.message); return;
  }
  timer = setTimeout(function () {
    if (done) return; done = true; w.terminate(); finish();
    FR.frames = [{ kind: 'error', state: { m: S.m, chains: defaultChainsEmpty(S.m) }, indices: [], message: '\u26d4 timed out (2 s) \u2014 worker terminated. Infinite loop?', kIdx: -1 }];
    setFrame(0); setStatus('#c62828', '\u26d4 timeout');
  }, 2000);
  w.onerror = function (e) {
    if (done) return; done = true; w.terminate(); finish();
    setStatus('#c62828', '\u26d4 ' + (e.message || 'worker error'));
  };
  w.onmessage = function (ev) {
    if (done) return; done = true; w.terminate(); finish();
    var res = ev.data;
    FR.frames = res.frames || [];
    if (!FR.frames.length) { setStatus('#c62828', '\u26d4 no frames produced'); return; }
    var last = FR.frames[FR.frames.length - 1].state.chains;
    var verdict = evaluateRun(last, res.error);
    setStatus(verdict.cls, verdict.text);
    S.bad = verdict.bad && verdict.bad.length ? verdict.bad : null;
    if (autoplay) { setFrame(0); pbPlay(); } else { setFrame(FR.frames.length - 1); }
    if (typeof cb === 'function') cb();
  };
  w.postMessage({ m: S.m, keys: S.keys.slice(), code: code, labels: labels });
}
function defaultChainsEmpty(m) { var c = []; for (var i = 0; i < m; i++) c.push([]); return c; }

/* ---------- playback ---------- */
function setFrame(i) {
  if (!FR.frames.length) return;
  FR.i = Math.max(0, Math.min(FR.frames.length - 1, i));
  var f = FR.frames[FR.i];
  S.m = f.state.m; S.chains = f.state.chains;
  S.flashSlot = (f.indices && f.indices.length) ? f.indices[0] : -1;
  S.flashK = (f.kIdx == null ? -1 : f.kIdx);
  document.getElementById('frameCounter').textContent = (FR.i + 1) + ' of ' + FR.frames.length;
  document.getElementById('frameCaption').textContent = f.message || '';
  var lines = [];
  for (var j = 0; j <= FR.i; j++) lines.push((j + 1) + '. ' + FR.frames[j].message);
  var lg = document.getElementById('runLog');
  lg.textContent = lines.join('\n'); lg.scrollTop = lg.scrollHeight;
  render();
}
function stopPlay() {
  if (FR.timer) { clearInterval(FR.timer); FR.timer = 0; }
  FR.playing = false;
  var b = document.getElementById('playBtn'); if (b) b.textContent = '\u25b6';
}
function pbPlay() {
  if (!FR.frames.length) return;
  if (FR.playing) { stopPlay(); return; }
  if (FR.i >= FR.frames.length - 1) setFrame(0);
  FR.playing = true; document.getElementById('playBtn').textContent = '\u23f8';
  var sp = +document.getElementById('speedInput').value || 1;
  FR.timer = setInterval(function () {
    if (FR.i >= FR.frames.length - 1) { stopPlay(); return; }
    setFrame(FR.i + 1);
  }, Math.max(90, 750 / sp));
}
function pbFirst() { stopPlay(); setFrame(0); }
function pbPrev() { stopPlay(); setFrame(FR.i - 1); }
function pbNext() { stopPlay(); setFrame(FR.i + 1); }

/* ---------- demo steps ---------- */
var STEPS = [
  {
    t: 'The universe and the actual keys',
    n: 'U holds every key that could ever occur; only the handful in K are really stored. T has far fewer slots than |U|, so some keys must share a slot.',
    go: function () { setAnn(false); setSlider(10); resetFigure(); }
  },
  {
    t: 'Run h(k) = k mod m',
    n: 'The code walks the keys and calls insert(k, k % m()). Each mapping arrow is drawn one at a time; when a second key reaches an occupied slot it is prepended in front of the node already there.',
    go: function () { setAnn(false); setSlider(10); setTab('sample'); trigger_hashCode(true); }
  },
  {
    t: 'A collision is just a longer list',
    n: 'One slot ends up with three keys and a three-node doubly linked chain; another holds one; the rest stay NIL. Chaining never rejects a key — it only lengthens a list. (Numeric detail is on: slot indices, key values, α.)',
    go: function () { setAnn(true); setSlider(10); setTab('sample'); trigger_hashCode(false, function () { setHighlight(5); }); }
  },
  {
    t: 'Shrink the table',
    n: 'Drop m to 5 and re-run: the same eight keys crowd into fewer slots, chains roughly double and α = n/m jumps — search cost follows chain length, not table size.',
    go: function () { setAnn(true); setSlider(5); setTab('sample'); trigger_hashCode(true); }
  },
  {
    t: 'A bad hash function',
    n: 'Load a hash that returns 0 for everything (or the Buggy tab with m ≠ 10): every key funnels into one slot and the table degenerates into a single linked list with Θ(n) search. Fix h and the chains flatten again.',
    go: function () { setAnn(false); setSlider(10); setTab('bad'); trigger_hashCode(true); }
  }
];
var stepIdx = 0;
function setStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[stepIdx];
  document.getElementById('demoNarration').innerHTML = '<b>' + s.t + '</b><br>' + s.n;
  document.getElementById('stepLabel').textContent = 'step ' + (stepIdx + 1) + ' / ' + STEPS.length;
  s.go();
}
function nextStep() { setStep(stepIdx + 1); }
function prevStep() { setStep(stepIdx - 1); }

/* ---------- init ---------- */
document.getElementById('hashCodeInput').addEventListener('input', function () {
  S.keys = parseKeys(); S.chains = defaultChains(); S.bad = null;
  FR.frames = []; FR.i = 0; stopPlay();
  document.getElementById('frameCounter').textContent = '0 of 0';
  setStatus('#666', 'keys changed \u2014 press Run');
  render();
});
setTab('sample');
S.keys = parseKeys();
S.chains = defaultChains();
setStatus('#666', 'not run \u2014 showing h(k) = k mod m');
setStep(0);
render();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A hash function h maps each actual key to a slot of table T, and when several keys collide they are simply strung together in that slot's doubly linked list — so the choice of h alone decides how evenly the keys spread and how long the chains get.
KEY INSIGHT (what students should walk away understanding): Chaining makes collisions harmless but not free — the hash function is the only thing standing between a table of short constant-time chains and one long linked list.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A hash function h maps each actual key to a slot of table T, and when several keys collide they are simply strung together in that slot's doubly linked list — so the choice of h alone decides how evenly the keys spread and how long the chains get.",
  "figureType": "diagram",
  "elements": [
    "Large outer ellipse filled medium gray, label 'U' (universe of keys) set large near its upper edge",
    "Inner ellipse filled light gray nested in U, label 'K' (actual keys) set large at its left edge",
    "Eight filled black key dots inside K, italic labels k₁…k₈ placed beside each dot with offsets chosen so no label overlaps a mapping arrow or a neighbouring dot",
    "Vertical column of equal-height slot rectangles forming table T, with a large 'T' label above the top slot",
    "Empty slots: dark-gray fill with a single diagonal NIL slash",
    "Occupied slots: near-white fill with a short horizontal head-pointer stub on the right edge",
    "Straight thin black arrows from each key dot in K to the left edge of its slot in T (the hash function made visible), crossing each other freely",
    "Four doubly linked chains to the right of T, one per occupied slot",
    "Each chain node drawn as a wide, tall three-field box: narrow prev-pointer field, wide center key-label field (k₁, k₄, …), narrow next-pointer field",
    "Long forward next-arrows along the upper link and long backward prev-arrows along the lower link between consecutive nodes, giving a clear double-link look",
    "Diagonal NIL slash in the prev field of each head node and the next field of each tail node",
    "Head arrow from each occupied slot's stub into the first node of its chain",
    "OPTIONAL (annotation toggle only): numeric key values under the dots, slot index digits 0..m-1 at the left edge of T, chain-length counts, and the α = n/m readout beneath T",
    "Small caption: diagonal slash = NIL"
  ],
  "interactions": [
    {
      "id": "hashCode",
      "type": "code_editor",
      "label": "Define the hash function and insert every key",
      "teaches": "That the entire chain structure — which slots stay NIL, which hold long lists — is produced by one expression h(k), and that a colliding key is simply prepended to the existing chain",
      "entry_point": "hashAll(keys)",
      "api": [
        {
          "op": "m()",
          "does": "returns the number of slots in T (set by the table-size slider)"
        },
        {
          "op": "insert(k, i)",
          "does": "prepends key k to the chain at slot i and draws its arrow from K — the ONLY way to change the figure; errors if i is not an integer in [0, m())"
        },
        {
          "op": "chainLength(i)",
          "does": "returns how many keys currently sit in slot i (read-only)"
        },
        {
          "op": "note(msg)",
          "does": "attaches your own comment to the current frame"
        }
      ],
      "frame": "the whole figure after one op: the arrow just drawn from the current key dot highlighted, the target slot flashing, and that slot's chain redrawn with the new head node",
      "input": {
        "label": "Actual keys (values of k₁…k₈)",
        "default": "11, 25, 17, 41, 15, 28, 35, 18"
      },
      "sample_code": "function hashAll(keys) {\n  for (const k of keys) {\n    const i = k % m();        // division method\n    note('h(' + k + ') = ' + i);\n    insert(k, i);\n  }\n}",
      "buggy_code": "function hashAll(keys) {\n  for (const k of keys) {\n    // BUG: table size hardcoded as 10 instead of m(),\n    // so slots go out of range (or are never used) when m changes\n    const i = k % 10;\n    insert(k, i);\n  }\n}",
      "success_check": "every input key appears in exactly one chain, and each key k sits in slot h(k) with 0 <= h(k) < m()"
    },
    {
      "id": "highlightChain",
      "type": "click",
      "teaches": "Which keys collided: clicking a slot lights up that slot, every key dot and mapping arrow that leads to it, and its whole chain — searching that slot means walking exactly that list"
    },
    {
      "id": "tableSize",
      "type": "slider",
      "label": "Table size m",
      "teaches": "How the same eight keys redistribute as m changes — a poor m piles keys into few slots and lengthens every chain",
      "range": [
        4,
        16,
        1
      ],
      "default": 10
    },
    {
      "id": "annotations",
      "type": "toggle",
      "label": "Show numeric detail (key values, slot indices, α)",
      "teaches": "Separates the structural idea (keys → slots → chains) from the bookkeeping numbers, which are hidden by default so the diagram stays as clean as the textbook figure",
      "default": false
    }
  ],
  "demo_steps": [
    {
      "title": "The universe and the actual keys",
      "narration": "U holds every key that could ever occur; only the handful in K are really stored. T has far fewer slots than |U|, so some keys must share a slot.",
      "state": {
        "tableSize": 10,
        "annotations": false
      }
    },
    {
      "title": "Run h(k) = k mod m",
      "narration": "The code walks the keys and calls insert(k, k % m()). Each mapping arrow is drawn one at a time; when a second key reaches an occupied slot it is prepended in front of the node already there.",
      "state": {
        "tableSize": 10,
        "annotations": false
      }
    },
    {
      "title": "A collision is just a longer list",
      "narration": "One slot ends up with three keys and a three-node doubly linked chain; another holds one; the rest stay NIL. Chaining never rejects a key — it only lengthens a list.",
      "state": {
        "tableSize": 10,
        "annotations": true
      }
    },
    {
      "title": "Shrink the table",
      "narration": "Drop m to 5 and re-run: the same eight keys crowd into fewer slots, chains roughly double and α = n/m jumps — search cost follows chain length, not table size.",
      "state": {
        "tableSize": 5,
        "annotations": true
      }
    },
    {
      "title": "A bad hash function",
      "narration": "Load the buggy version (or write `return 0`): every key funnels into one slot and the table degenerates into a single linked list with Θ(n) search. Fix h and the chains flatten again.",
      "state": {
        "tableSize": 10,
        "annotations": false
      }
    }
  ],
  "keyInsight": "Chaining makes collisions harmless but not free — the hash function is the only thing standing between a table of short constant-time chains and one long linked list.",
  "reconstructionNotes": "LAYOUT FIRST: call setUiLayout to dock the code editor and controls BELOW the drawing; the SVG must span the full canvas width with no side panel. Use a wide viewBox (roughly 3:2) and three left→right bands: (1) the U/K ellipses on the left third, (2) the vertical slot column T in the middle, (3) the four chains on the right half, with enough right-hand room that the longest three-node chain fits without shrinking. Typography: 'U', 'K', 'T' at ≥20 viewBox px bold/italic as in the source; k₁…k₈ and node key labels ≥16 px. No text smaller than 14 px anywhere; the optional numeric detail appears only when the annotations toggle is on. Do NOT draw chain-length badges, '×N' counters, per-slot index digits, or numeric key values by default. Key-dot labels sit clear of the mapping arrows — place k₂, k₇, k₈ above-left of their dots and k₃ below-left so no label crosses an arrow or touches a neighbouring dot. Chain nodes must be visually generous: each node a wide, tall rectangle divided into narrow-prev / wide-center / narrow-next fields (center field at least twice the width of a pointer field), with a clear gap between nodes spanned by a long forward arrow on the upper link and a long backward arrow on the lower link, so the doubly linked structure reads at a glance. Colors: U medium gray, K light gray, empty slots dark gray with a NIL slash, occupied slots near-white, node boxes white with black strokes. Click highlighting tints one slot, its incoming arrows, its key dots and its whole chain in a single accent (orange) while everything else dims to light gray. During code replay the newly inserted head node flashes."
}

