// @FIGURE_CODE_BEGIN
var FW = 820, FH = 520;
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, FW, FH);
var figScene = figDraw.group();

var ACCENT = '#e8791e', DIMOP = 0.22;
var SERIF = 'Georgia,"Times New Roman",serif';
var SANS = 'Helvetica,Arial,sans-serif';

/* ---------- geometry ---------- */
var UCX = 150, UCY = 250, URX = 145, URY = 205;
var KCX = 148, KCY = 285, KRX = 106, KRY = 131;
var TX = 385, TW = 62, TTOP = 44, TBOT = 470;
var CX0 = 490;

/* Key dots follow the source layout. Every label is placed to the LEFT of its
   dot (as in the textbook), so no label can ever cross a mapping arrow; the
   dot positions are chosen so the label boxes never overlap each other,
   a neighbouring dot, or the K caption. */
var KEYPOS = [
  { x: 105, y: 219 },   /* k1 */
  { x: 128, y: 328 },   /* k2 */
  { x: 222, y: 337 },   /* k3 */
  { x: 120, y: 263 },   /* k4 */
  { x: 197, y: 264 },   /* k5 */
  { x: 93, y: 363 },   /* k6 */
  { x: 160, y: 288 },   /* k7 */
  { x: 170, y: 347 }    /* k8 */
];
var LBL_DX = -14;
var SUB = ['\u2081', '\u2082', '\u2083', '\u2084', '\u2085', '\u2086', '\u2087', '\u2088', '\u2089'];
function klabel(i) { return 'k' + (i < 9 ? SUB[i] : String(i + 1)); }
function plain(i) { return 'k' + (i + 1); }

var S = { m: 10, keys: [11, 25, 17, 41, 15, 28, 35, 18], chains: [], highlight: null, flashSlot: -1, flashK: -1, bad: null, ann: false };
var FR = { frames: [], i: 0, timer: 0, playing: false, running: false };

/* ---------- small helpers ---------- */
function txt(g, x, y, s, size, o) {
  o = o || {};
  var t = g.text(String(s));
  t.font({ family: o.family || SERIF, size: size, anchor: o.anchor || 'middle', style: o.italic ? 'italic' : 'normal', weight: o.weight || 'normal', leading: 1 });
  t.fill(o.fill || '#000');
  t.attr({ x: x, y: y });
  t.attr('dominant-baseline', 'central');
  var kids = t.node.childNodes;
  for (var i = 0; i < kids.length; i++) { if (kids[i].setAttribute) { kids[i].setAttribute('x', x); kids[i].setAttribute('dy', 0); } }
  t.attr('pointer-events', 'none');
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: o.haloFill || '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
