  '  var frames = [], ops = 0, t0 = Date.now(), used = [];',
  '  function copy(){ var c=[]; for(var a=0;a<chains.length;a++){ var r=[]; for(var b=0;b<chains[a].length;b++){ var n=chains[a][b]; r.push({label:n.label,value:n.value,kIdx:n.kIdx}); } c.push(r);} return c; }',
  '  function push(kind, idx, msg, kIdx){ frames.push({kind:kind,state:{m:m,chains:copy()},indices:idx,message:msg,kIdx:(kIdx==null?-1:kIdx)}); if(frames.length>300) throw new Error("__CAP__frame cap (300) reached \u2014 is your loop terminating?"); }',
